-- Restored-backup data of the load fixture's db node (tools/tests, v0.3
-- chunk 12; fixture-audit's data, with orders.id an identity column so the
-- producer can insert, and the schedulers' two roles). gmctl load-data
-- streams this file into
--   psql -X -q -v ON_ERROR_STOP=1 -d postgres
-- run as the postgres OS user; the file creates its own roles and databases.
-- The schedulers' roles log in; their passwords are the game's secrets,
-- set by load-data (capture W1 item 7), never written here.
CREATE ROLE shop NOLOGIN;
CREATE ROLE shop_app LOGIN;
CREATE ROLE shop_reports LOGIN;
CREATE DATABASE shop OWNER shop;

\connect shop
SET ROLE shop;

CREATE TABLE customers (
    id   integer PRIMARY KEY,
    name text    NOT NULL
);

CREATE TABLE orders (
    id          integer       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    customer_id integer       NOT NULL REFERENCES customers (id),
    placed_at   timestamptz   NOT NULL,
    total       numeric(10,2) NOT NULL
);

INSERT INTO customers (id, name)
SELECT g, 'customer ' || g FROM generate_series(1, 500) AS g;

INSERT INTO orders (id, customer_id, placed_at, total)
SELECT g, 1 + g % 500, timestamptz '2026-01-01 00:00:00+00' + g * interval '7 minutes',
       (g % 97) + 0.99
  FROM generate_series(1, 20000) AS g;
SELECT setval(pg_get_serial_sequence('orders', 'id'), 20000);

CREATE INDEX orders_customer_id_idx ON orders (customer_id);

-- The order service writes orders and reads both tables; the reporting
-- service only reads.
GRANT SELECT ON customers TO shop_app, shop_reports;
GRANT SELECT, INSERT ON orders TO shop_app;
GRANT SELECT ON orders TO shop_reports;
GRANT USAGE ON SEQUENCE orders_id_seq TO shop_app;

ANALYZE customers;
ANALYZE orders;
